import { createRng } from "../../lib/ecs-js/rng.js";
import { Monster } from "../archetypes/Creatures.js";
import { Equipment, GEAR_SLOT_SET } from "../components/Equipment.js";
import { Inventory } from "../components/Inventory.js";
